-- Generated by Supabase CLI. Authorized for synthetic in-memory tests only;
-- NOT authorized/applied to hosted STAGING, recovery copy or production.
-- Requires 044-050. No data rewrite/deletion, bucket change or policy expansion.
begin;

-- Preserve 046's complete guard; add only an owner-active status-only withdrawal.
create or replace function public.qrih_protect_property_fields()
returns trigger language plpgsql security definer set search_path='' as $$
declare v_field text; v_number numeric;
begin
  if tg_op='UPDATE' and auth.uid() is not null and old.owner_id=auth.uid()
    and new.owner_id=old.owner_id and public.qrih_actor_is_active()
    and old.status::text='published' and new.status::text='draft'
    and (to_jsonb(new)-array['status','updated_at'])=(to_jsonb(old)-array['status','updated_at']) then
    new.updated_at:=clock_timestamp();
    insert into public.audit_logs(actor_id,entity_type,entity_id,action,metadata)
      values(auth.uid(),'property',old.id,'property_withdrawn_for_edit',
        jsonb_build_object('previous_status','published','status','draft'));
    return new;
  end if;
  if auth.uid() is not null and not public.current_user_is_admin() then
    if not public.qrih_actor_is_active() or new.owner_id<>auth.uid()
      or new.status::text not in ('draft','pending') then raise exception 'No puedes guardar la propiedad en ese estado.'; end if;
    if tg_op='INSERT' then
      if coalesce(new.featured,false) or new.featured_priority is not null
        or new.last_verified_at is not null or new.verification_due_at is not null
        or new.rejection_reason is not null or new.main_image is not null then
        raise exception 'No puedes asignar campos de moderación.';
      end if;
    else
      if old.status::text not in ('draft','rejected') then raise exception 'Sólo puedes editar borradores o propiedades rechazadas.'; end if;
      foreach v_field in array array['id','owner_id','created_at','featured','featured_priority',
        'last_verified_at','verification_due_at','main_image','previous_data'] loop
        if to_jsonb(new)->v_field is distinct from to_jsonb(old)->v_field then raise exception 'No puedes modificar campos de moderación.'; end if;
      end loop;
    end if;
  end if;
  if length(trim(new.title)) not between 1 and 200 or length(new.description)>10000
    or new.total_area<0 or new.covered_area<0 or new.exterior_area<0
    or new.offices_area<0 or new.parking<0 or new.docks<0 then raise exception 'Datos de propiedad inválidos.'; end if;
  foreach v_field in array array['price_value','total_area','covered_area','exterior_area','offices_area','parking','docks'] loop
    v_number:=(to_jsonb(new)->>v_field)::numeric;
    if v_number<0 or v_number>1e12 then raise exception 'Cantidad fuera de rango.'; end if;
  end loop;
  if length(new.zone)>160 or length(new.zone_general)>160 or length(new.address)>1000
    or length(new.price_display)>80 or length(new.max_height)>80 then raise exception 'Datos de propiedad demasiado largos.'; end if;
  new.updated_at:=clock_timestamp();
  return new;
end $$;
revoke all on function public.qrih_protect_property_fields() from public,anon,authenticated;

create function public.qrih_withdraw_own_property(p_property_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_property public.properties;
begin
  if auth.uid() is null or not public.qrih_actor_is_active() then raise exception 'Cuenta no autorizada.'; end if;
  select * into v_property from public.properties where id=p_property_id for update;
  if not found or v_property.owner_id<>auth.uid() then raise exception 'Propiedad no disponible.'; end if;
  -- Safe retry after response loss; no second transition or audit entry.
  if v_property.status::text='draft' then return v_property.id; end if;
  if v_property.status::text<>'published' then raise exception 'Estado no editable.'; end if;
  update public.properties set status='draft' where id=p_property_id;
  return p_property_id;
end $$;
revoke all on function public.qrih_withdraw_own_property(uuid) from public,anon,authenticated;
grant execute on function public.qrih_withdraw_own_property(uuid) to authenticated;

create unique index qrih_duplicate_request_unique on public.audit_logs(actor_id,(metadata->>'request_id'))
  where action='property_duplicated';

create function public.qrih_duplicate_property(p_source_id uuid,p_request_id uuid,p_changes jsonb default null,p_images jsonb default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_source public.properties; v_new public.properties; v_id uuid; v_existing uuid; v_path text;
begin
  if auth.uid() is null or not public.qrih_actor_is_active() or p_request_id is null then raise exception 'Cuenta no autorizada.'; end if;
  select * into v_source from public.properties where id=p_source_id for share;
  if not found or v_source.owner_id<>auth.uid() then raise exception 'Propiedad no disponible.'; end if;
  -- Serialize only the same actor/attempt, never network calls inside transaction.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text||p_request_id::text,0));
  select l.entity_id into v_existing from public.audit_logs l join public.properties p on p.id=l.entity_id
    where l.actor_id=auth.uid() and l.action='property_duplicated'
      and l.metadata->>'request_id'=p_request_id::text and l.metadata->>'source_id'=p_source_id::text
      and p.owner_id=auth.uid();
  if found then return v_existing; end if;
  -- Preflight/idempotency lookup, no row or file is created.
  if p_changes is null and p_images is null then return null; end if;
  if p_changes is null or jsonb_typeof(p_changes)<>'object' or exists(
    select 1 from jsonb_object_keys(p_changes) k where k not in (
      'title','operation','price_display','price_value','price_unit','price_plus_vat','price_plus_maintenance','negotiable',
      'zone_general','zone','location_visibility','address','total_area','covered_area','exterior_area',
      'max_height','offices_area','parking','docks','description','share_commission','status'))
    or p_changes->>'status' is distinct from 'draft' then raise exception 'Campos de creación inválidos.'; end if;
  if p_images is null or jsonb_typeof(p_images)<>'array' or jsonb_array_length(p_images) not between 0 and 7 then raise exception 'Galería inválida.'; end if;
  for v_path in select distinct i->>'storage_path' from jsonb_array_elements(p_images) i order by 1 loop
    if v_path is null then raise exception 'Ruta inválida.'; end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('qrih-copy:'||v_path,0));
  end loop;
  if exists(select 1 from jsonb_array_elements(p_images) i
    where public.qrih_valid_image_reference(auth.uid(),i->>'storage_path') is not true
      or exists(select 1 from public.property_images where storage_path=i->>'storage_path')
      or exists(select 1 from public.properties where main_image_path=i->>'storage_path')) then
    raise exception 'Las fotografías deben ser propias e independientes.';
  end if;
  v_new:=jsonb_populate_record(null::public.properties,p_changes);
  if v_new.price_value is null or v_new.price_value<=0 or v_new.price_value>1e12
    or v_new.price_unit is distinct from (case when v_new.operation='Renta' then 'm2' else 'total' end) then
    raise exception 'Precio inválido.';
  end if;
  v_id:=gen_random_uuid();
  -- Only commercial values. All internal fields use defaults/null, no source clone.
  insert into public.properties(id,owner_id,slug,title,operation,status,zone_general,zone,
    location_visibility,address,price_display,price_value,price_unit,price_plus_vat,price_plus_maintenance,negotiable,
    total_area,covered_area,exterior_area,max_height,offices_area,parking,docks,description,share_commission)
    values(v_id,auth.uid(),'bodega-'||v_id::text,v_new.title,v_new.operation,'draft',v_new.zone_general,v_new.zone,
      v_new.location_visibility,v_new.address,v_new.price_display,v_new.price_value,v_new.price_unit,v_new.price_plus_vat,v_new.price_plus_maintenance,v_new.negotiable,
      v_new.total_area,v_new.covered_area,v_new.exterior_area,v_new.max_height,v_new.offices_area,v_new.parking,v_new.docks,v_new.description,v_new.share_commission);
  if jsonb_array_length(p_images)>0 then
    perform public.replace_property_images(v_id,p_images);
    update public.properties set main_image_path=p_images->0->>'storage_path' where id=v_id;
  end if;
  insert into public.audit_logs(actor_id,entity_type,entity_id,action,metadata)
    values(auth.uid(),'property',v_id,'property_duplicated',jsonb_build_object('source_id',p_source_id,'request_id',p_request_id));
  return v_id;
end $$;
revoke all on function public.qrih_duplicate_property(uuid,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.qrih_duplicate_property(uuid,uuid,jsonb,jsonb) to authenticated;
commit;
